*** Begin Patch
*** Add File: src/cli.ts
+type Task = {
+  id: string;
+  duration: number;
+  dependsOn: string[];
+};
+
+type Plan = {
+  order: string[];
+  layers: string[][];
+  earliest: Record<string, { start: number; finish: number }>;
+  totalDuration: number;
+  criticalPath: string[];
+};
+
+function fail(message: string): never {
+  console.error(`Error: ${message}`);
+  process.exit(1);
+}
+
+function isRecord(value: unknown): value is Record<string, unknown> {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function validate(input: unknown): Task[] {
+  if (!isRecord(input) || !Array.isArray(input.tasks)) {
+    fail('input must be an object with a "tasks" array');
+  }
+
+  const tasks: Task[] = [];
+  const ids = new Set<string>();
+  for (let index = 0; index < input.tasks.length; index++) {
+    const value = input.tasks[index];
+    if (!isRecord(value)) fail(`tasks[${index}] must be an object`);
+    if (typeof value.id !== "string" || value.id.length === 0) {
+      fail(`tasks[${index}].id must be a non-empty string`);
+    }
+    if (ids.has(value.id)) fail(`duplicate task id: ${value.id}`);
+    if (typeof value.duration !== "number" || !Number.isFinite(value.duration) || value.duration < 0) {
+      fail(`tasks[${index}].duration must be a finite non-negative number`);
+    }
+    const dependsOn = value.dependsOn === undefined ? [] : value.dependsOn;
+    if (!Array.isArray(dependsOn) || !dependsOn.every((id) => typeof id === "string")) {
+      fail(`tasks[${index}].dependsOn must be an array of strings`);
+    }
+    if (new Set(dependsOn).size !== dependsOn.length) {
+      fail(`tasks[${index}].dependsOn must contain unique ids`);
+    }
+    tasks.push({ id: value.id, duration: value.duration, dependsOn: [...dependsOn] });
+    ids.add(value.id);
+  }
+
+  for (const task of tasks) {
+    for (const dependency of task.dependsOn) {
+      if (dependency === task.id) fail(`task ${task.id} cannot depend on itself`);
+      if (!ids.has(dependency)) fail(`task ${task.id} depends on unknown task: ${dependency}`);
+    }
+  }
+  return tasks;
+}
+
+function findCycle(tasks: Task[], byId: Map<string, Task>): string[] | undefined {
+  const state = new Map<string, number>();
+  const stack: string[] = [];
+  const visit = (id: string): string[] | undefined => {
+    state.set(id, 1);
+    stack.push(id);
+    for (const dependency of [...byId.get(id)!.dependsOn].sort()) {
+      if (state.get(dependency) === 1) return [...stack.slice(stack.indexOf(dependency)), dependency];
+      if (state.get(dependency) !== 2) {
+        const cycle = visit(dependency);
+        if (cycle) return cycle;
+      }
+    }
+    stack.pop();
+    state.set(id, 2);
+  };
+  for (const task of [...tasks].sort((a, b) => a.id.localeCompare(b.id))) {
+    if (!state.has(task.id)) {
+      const cycle = visit(task.id);
+      if (cycle) return cycle;
+    }
+  }
+}
+
+function makePlan(tasks: Task[]): Plan {
+  const byId = new Map(tasks.map((task) => [task.id, task]));
+  const cycle = findCycle(tasks, byId);
+  if (cycle) fail(`dependency cycle: ${cycle.join(" -> ")}`);
+
+  const dependents = new Map(tasks.map((task) => [task.id, [] as string[]]));
+  const remaining = new Map(tasks.map((task) => [task.id, task.dependsOn.length]));
+  for (const task of tasks) for (const dependency of task.dependsOn) dependents.get(dependency)!.push(task.id);
+  for (const values of dependents.values()) values.sort();
+
+  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort();
+  const order: string[] = [];
+  while (ready.length > 0) {
+    const id = ready.shift()!;
+    order.push(id);
+    for (const dependent of dependents.get(id)!) {
+      const count = remaining.get(dependent)! - 1;
+      remaining.set(dependent, count);
+      if (count === 0) {
+        ready.push(dependent);
+        ready.sort();
+      }
+    }
+  }
+
+  const earliest: Plan["earliest"] = {};
+  const paths = new Map<string, string[]>();
+  const layers: string[][] = [];
+  for (const id of order) {
+    const task = byId.get(id)!;
+    let start = 0;
+    let parentPath: string[] = [];
+    for (const dependency of task.dependsOn) {
+      const candidateStart = earliest[dependency].finish;
+      const candidatePath = paths.get(dependency)!;
+      if (candidateStart > start || (candidateStart === start && candidatePath.join("\0") < parentPath.join("\0"))) {
+        start = candidateStart;
+        parentPath = candidatePath;
+      }
+    }
+    earliest[id] = { start, finish: start + task.duration };
+    paths.set(id, [...parentPath, id]);
+    const layer = task.dependsOn.length === 0 ? 0 : Math.max(...task.dependsOn.map((dependency) => layers.findIndex((items) => items.includes(dependency)) + 1));
+    while (layers.length <= layer) layers.push([]);
+    layers[layer].push(id);
+  }
+  for (const layer of layers) layer.sort();
+
+  let totalDuration = 0;
+  let criticalPath: string[] = [];
+  for (const id of order) {
+    const finish = earliest[id].finish;
+    const path = paths.get(id)!;
+    if (finish > totalDuration || (finish === totalDuration && path.join("\0") < criticalPath.join("\0"))) {
+      totalDuration = finish;
+      criticalPath = path;
+    }
+  }
+  return { order, layers, earliest, totalDuration, criticalPath };
+}
+
+const args = process.argv.slice(2);
+if (args.length !== 2 || args[0] !== "plan" || args[1].startsWith("-")) {
+  fail("usage: bun run src/cli.ts plan INPUT.json");
+}
+
+let parsed: unknown;
+try {
+  parsed = JSON.parse(await Bun.file(args[1]).text());
+} catch (error) {
+  fail(`could not read valid JSON from ${args[1]}: ${error instanceof Error ? error.message : String(error)}`);
+}
+console.log(JSON.stringify(makePlan(validate(parsed))));
*** Add File: README.md
+# Dependency Planner
+
+Dependency-free TypeScript CLI for Bun that validates a task dependency graph and calculates an execution plan.
+
+## Usage
+
+```sh
+bun run src/cli.ts plan INPUT.json
+```
+
+The input is a JSON object with a `tasks` array. Every task has a unique `id`, a finite non-negative `duration`, and an optional `dependsOn` array:
+
+```json
+{"tasks":[{"id":"lint","duration":1},{"id":"build","duration":3,"dependsOn":["lint"]}]}
+```
+
+The command prints one JSON object containing a deterministic topological `order`, concurrent `layers`, per-task `earliest` timings, `totalDuration`, and a lexicographically tie-broken `criticalPath`. Invalid input and cycles exit non-zero with an error on stderr.
*** End Patch

