import { mkdtemp, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

const root = process.cwd();
const dir = await mkdtemp(join(tmpdir(), "dependency-planner-test-"));
let counter = 0;

async function run(input: unknown, args = ["plan"]): Promise<{ code: number; out: string; err: string }> {
  const file = join(dir, `${counter++}.json`);
  await writeFile(file, typeof input === "string" ? input : JSON.stringify(input));
  const proc = Bun.spawn(["bun", "run", "src/cli.ts", ...args, file], { cwd: root, stdout: "pipe", stderr: "pipe" });
  return { code: await proc.exited, out: await new Response(proc.stdout).text(), err: await new Response(proc.stderr).text() };
}
function equal(actual: unknown, expected: unknown, label: string) {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`${label}\nactual: ${JSON.stringify(actual)}\nexpected: ${JSON.stringify(expected)}`);
}
try {
  let result = await run({ tasks: [
    { id: "build", duration: 3, dependsOn: ["lint", "test"] },
    { id: "test", duration: 2, dependsOn: ["lint"] },
    { id: "lint", duration: 1 },
    { id: "docs", duration: 4 }
  ] });
  if (result.code !== 0 || result.err) throw new Error(`valid graph failed: ${result.err}`);
  equal(JSON.parse(result.out), {
    order: ["docs", "lint", "test", "build"],
    layers: [["docs", "lint"], ["test"], ["build"]],
    earliest: { build: { start: 3, finish: 6 }, docs: { start: 0, finish: 4 }, lint: { start: 0, finish: 1 }, test: { start: 1, finish: 3 } },
    totalDuration: 6,
    criticalPath: ["lint", "test", "build"]
  }, "valid graph");

  result = await run({ tasks: [{ id: "b", duration: 0, dependsOn: ["a"] }, { id: "a", duration: 0 }] });
  if (result.code !== 0) throw new Error(`zero duration failed: ${result.err}`);
  equal(JSON.parse(result.out).criticalPath, ["a", "b"], "zero-duration critical path");

  result = await run({ tasks: [{ id: "b", duration: 1 }, { id: "a", duration: 1 }] });
  equal(JSON.parse(result.out).criticalPath, ["a"], "equal critical paths");

  result = await run({ tasks: [{ id: "b", duration: 1, dependsOn: ["a"] }, { id: "a", duration: 1, dependsOn: ["b"] }] });
  if (result.code === 0 || !result.err.includes("a -> b -> a")) throw new Error(`cycle handling failed: ${result.err}`);

  result = await run({ tasks: [{ id: "a", duration: 1, dependsOn: ["missing"] }] });
  if (result.code === 0 || !result.err.includes("unknown task")) throw new Error(`unknown dependency failed: ${result.err}`);

  result = await run("{not json");
  if (result.code === 0 || !result.err.includes("Invalid JSON")) throw new Error(`invalid JSON failed: ${result.err}`);

  result = await run({ tasks: [] }, ["unknown"]);
  if (result.code === 0 || !result.err.includes("Usage")) throw new Error(`unknown command failed: ${result.err}`);

  console.log("all self-tests passed");
} finally {
  await rm(dir, { recursive: true, force: true });
}
